package com.merakianalytics.core;

import java.util.HashSet;
import java.util.Set;

import javax.inject.Inject;
import javax.ws.rs.ApplicationPath;
import javax.ws.rs.core.Application;

import com.merakianalytics.core.exceptions.OriannaExceptionMapper;
import com.merakianalytics.core.exceptions.QueryValidationExceptionMapper;
import com.merakianalytics.core.filters.CORSFilter;
import com.merakianalytics.core.filters.NullResponseFilter;
import com.merakianalytics.core.providers.JSONProvider;
import com.merakianalytics.core.providers.MessagePackProvider;

/**
 * The jax-rs application specification. This is the "main" of the core application.
 */
@ApplicationPath("/lol")
public class Kernel extends Application {
    @Inject
    private KernelContext context;

    @Override
    public Set<Class<?>> getClasses() {
        final Set<Class<?>> services = new HashSet<>();

        // Utilities
        services.add(OriannaExceptionMapper.class);
        services.add(QueryValidationExceptionMapper.class);
        services.add(CORSFilter.class);
        services.add(NullResponseFilter.class);
        services.add(JSONProvider.class);
        services.add(MessagePackProvider.class);

        // Riot API
        if(context.isProduceCoreData()) {
            services.add(com.merakianalytics.core.riotapi.data.ChampionMasteryAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.ChampionAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.LeagueAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.StatusAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.MatchAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.SpectatorAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.SummonerAPI.class);
            services.add(com.merakianalytics.core.riotapi.data.ThirdPartyCodeAPI.class);
        } else {
            services.add(com.merakianalytics.core.riotapi.dto.ChampionMasteryAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.ChampionAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.LeagueAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.StatusAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.MatchAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.SpectatorAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.SummonerAPI.class);
            services.add(com.merakianalytics.core.riotapi.dto.ThirdPartyCodeAPI.class);
        }

        return services;
    }
}

